// Hostile sprite IDs from snesrev/zelda3's kSpriteActiveRoutines.
// Explicit classification keeps NPCs, items, switches and room machinery safe.
export const ENEMIES=new Set([
  0x00,0x01,0x02,0x08,0x09,0x0a,0x0d,0x0e,0x0f,0x10,0x11,0x12,0x13,
  0x15,0x17,0x18,0x19,0x20,0x22,0x23,0x24,0x26,0x27,0x3e,
  0x41,0x42,0x43,0x44,0x45,0x46,0x47,0x48,0x49,0x4a,0x4b,0x4c,0x4d,0x4e,0x4f,
  0x51,0x53,0x54,0x55,0x56,0x58,0x5b,0x5c,0x61,0x64,0x6a,0x6b,0x6d,0x6e,0x6f,
  0x71,0x77,0x79,0x7a,0x7c,0x80,0x81,0x82,0x83,0x84,0x85,0x86,0x88,
  0x8b,0x8c,0x8d,0x8e,0x8f,0x90,0x91,0x92,0x94,0x99,0x9a,0x9b,0x9c,0x9d,
  0xa1,0xa2,0xa3,0xa5,0xa6,0xa7,0xa8,0xa9,0xaa,0xbd,0xbe,
  0xc3,0xc4,0xc7,0xc9,0xca,0xcb,0xcc,0xcd,0xce,0xcf,0xd0,0xd3,0xd4,0xd6,0xd7,
]);
export const BOSSES=new Set([0x09,0x53,0x54,0x7a,0x88,0x8c,0x92,0xa2,0xa3,0xbd,0xcb,0xcc,0xcd,0xce,0xd6,0xd7]);
// These initialize at zero HP but are live enemies, not defeated sprites.
export const ZERO_HEALTH_ENEMIES=new Set([0x10,0x79,0x86,0xc4,0xd4]);
// Some boss IDs also represent detached heads, magic or debris. Their original
// scripts own these objects and the transitions after the actual boss is beaten.
export function enemyBody(ram,a,slot){
  const type=ram[a.type+slot],ai=ram[a.ai+slot];
  if(!ENEMIES.has(type))return false;
  if(type===0xce&&ram[a.a+slot]!==0)return false; // Blind's heads and lasers
  if((type===0xcc||type===0xcd)&&ram[a.e+slot])return false; // Trinexx magic
  if(type===0x92&&(ram[a.c+slot]&0x80))return false; // Mask fragments
  if(type===0xc9&&ram[a.anim+slot])return false; // Ganon's trident/cutscene/fire bats
  if(type===0x55&&ram[a.e+slot])return false; // Zora/Agahnim fireball, not its owner
  if(type===0x7a&&(slot!==0||ai<3||ai>=8))return false; // Clones/intro/exit
  if(type===0xcb&&!ram[a.trinexxFinal])return false; // Side heads unlock the body
  if(BOSSES.has(type)&&ai>=0x80)return false;
  if(type===0x09&&ai===3||type===0x54&&ai===5||type===0xa1&&ai===3||type===0xa3&&ai!==0)return false;
  if(type===0xa2&&ai===2)return false; // Shell breaking / triplication
  return true;
}
